begin;

-- Authorial V5 content is compiled for review but remains inactive and unaligned.
-- No student can receive it until separate pedagogical and publication gates pass.
do $seed_question_first_content_v5$
declare
  v_catalog_id uuid;
  v_skill_id uuid;
  v_lesson_id uuid;
  v_set_id uuid;
  v_question_id uuid;
  v_question record;
begin
  select id into v_catalog_id
    from public.learning_curriculum_catalogs
   where code = 'TECESCOLA_CORE' and version = '1.0'
   limit 1;
  if v_catalog_id is null then raise exception 'V5_CONTENT_CATALOG_MISSING'; end if;
  select id into v_skill_id
    from public.learning_curriculum_skills
   where catalog_id = v_catalog_id and code = 'BIOLOGY_INTERPRET_POPULATION_DATA';
  if v_skill_id is null then raise exception 'V5_CONTENT_SKILL_MISSING'; end if;

  insert into public.learning_skill_lessons(
    canonical_skill_id, version, title, summary, content_markdown,
    worked_example, tips, estimated_minutes, active, metadata
  ) values (
    v_skill_id, 5, 'Populações: medir, comparar e explicar tendências', 'Uma contagem é uma observação, não uma explicação completa. Unidades, esforço, detectabilidade, entradas e saídas ajudam a interpretar como uma população muda no espaço e no tempo.', '## Primeiro, saiba o que foi medido
Abundância é o número de indivíduos estimado numa população; densidade relaciona esse número a uma área ou volume. Uma contagem maior pode ocorrer apenas porque a área ou o esforço de observação foi maior. Registre unidade, período, método e local antes de comparar.

## Amostrar sem confundir observação com realidade
Quadrantes e outras amostras devem representar os ambientes que compõem a área. Estratificar por habitat e sortear locais reduz o risco de observar somente pontos acessíveis ou densos. Para animais móveis, captura-recaptura pode estimar abundância: N≈M×C/R, onde M é o número marcado e solto, C o total da segunda amostra e R as recapturas reconhecidas. A estimativa simples pressupõe população aproximadamente fechada no intervalo, mistura, marcas persistentes e chance semelhante de captura.

## Leia a dinâmica antes de propor uma causa
O tamanho muda com nascimentos, mortes, imigração e emigração. Recursos limitados podem desacelerar o crescimento à medida que a população se aproxima de um patamar; esse patamar varia com estação, clima e habitat. Fatores dependentes da densidade tendem a exercer efeitos diferentes conforme a concentração; eventos como geadas podem afetar populações em densidades distintas.

## Compare hipóteses
Uma queda observada pode significar mortalidade, emigração, menor detecção ou mudança no método. Uma associação com seca, restauração ou vegetação é uma hipótese, não uma causa provada por um gráfico isolado. Use locais de comparação, medidas repetidas, protocolo consistente e dados complementares para testar explicações.

## Exemplo resolvido
No primeiro esforço, 120 lontras são marcadas e soltas. Na segunda amostra, 60 são observadas, incluindo 10 marcas reconhecidas. O estimador simples dá N≈120×60/10=720. Esse valor é uma estimativa, não uma contagem exata. Se marcas se soltarem, R pode cair e a estimativa subir artificialmente; se os indivíduos marcados ainda não se misturaram, R pode ficar alto e a estimativa baixa.',
    'Quatro quadrantes sorteados de 5 m² registram 18, 22, 15 e 25 plantas: a densidade média amostral é (18+22+15+25)/(4×5)=4 plantas/m². Essa estimativa representa o estrato amostrado; se áreas abertas e úmidas forem diferentes, sorteie em ambos e pondere pelo tamanho de cada estrato. Uma diferença entre anos só indica tendência se método, período e detectabilidade forem comparáveis.', array['Anote a unidade, área, tempo e esforço junto de cada medida.', 'Separe resultado observado de hipótese causal.', 'Verifique se o protocolo e a probabilidade de detecção são comparáveis.', 'Diga quais premissas sustentam uma estimativa e o que poderia enviesá-la.']::text[], 24, false, '{"content_pack":"TECESCOLA_CORE_V5_QUESTION_FIRST","content_id":"v5-biology-population-data","content_authoring_status":"AUTHORED","pedagogical_review_status":"PEDAGOGICAL_REVIEW_PENDING","publication_status":"STAGING","bncc_alignment_status":"NOT_CLAIMED","prior_knowledge":["Calcular razões, médias e variações percentuais.","Distinguir uma observação de uma explicação causal."],"key_concepts":["abundância, densidade e estrutura etária","amostragem aleatória e estratificada","captura-recaptura e suas premissas","natalidade, mortalidade, imigração e emigração","crescimento exponencial e logístico","fatores dependentes e independentes da densidade","detectabilidade, viés e inferência causal"],"progression":[{"stage":"FOUNDATION","focus":"Comparar medidas e reconhecer viés de seleção.","questionIds":["v5-bio-population-probe-01","v5-bio-population-probe-02"]},{"stage":"APPLICATION","focus":"Calcular estimativas e interpretar patamares com premissas.","questionIds":["v5-bio-population-practice-01","v5-bio-population-practice-02","v5-bio-population-practice-03"]},{"stage":"TRANSFER","focus":"Avaliar estimadores, desenho comparativo e estrutura etária.","questionIds":["v5-bio-population-transfer-01","v5-bio-population-transfer-02","v5-bio-population-transfer-03"]},{"stage":"INTEGRATION","focus":"Integrar fatores ambientais, entradas e saídas populacionais.","questionIds":["v5-bio-population-lock-01","v5-bio-population-lock-02","v5-bio-population-lock-03"]},{"stage":"SPACED_REVIEW_CANDIDATE","focus":"Revisar amostragem, modelos e limites de observação; o agendamento depende do produto.","questionIds":["v5-bio-population-review-01","v5-bio-population-review-02","v5-bio-population-review-03","v5-bio-population-review-04","v5-bio-population-review-05","v5-bio-population-review-06"]}],"micro_explanations":[{"trigger":"ABUNDANCE_DENSITY","text":"Abundância é o total; densidade divide esse total por área ou volume."},{"trigger":"SAMPLE_BIAS","text":"Muitas observações em locais acessíveis ainda podem deixar habitats inteiros sem representação."},{"trigger":"MARK_RECAPTURE","text":"Na estimativa simples, aumente M ou C para elevar N; aumente R para reduzi-lo."},{"trigger":"POPULATION_BALANCE","text":"Nascimentos e imigração adicionam indivíduos; mortes e emigração reduzem o tamanho local."},{"trigger":"DETECTION","text":"Menos registros podem refletir menor abundância ou menor chance de observar cada indivíduo."},{"trigger":"MODEL_LIMIT","text":"Uma curva compatível com um modelo não prova sozinha qual mecanismo causou a tendência."}],"remediations":[{"id":"STANDARDIZE_DENSITY","misconception":"CONFUNDIR_ABUNDANCIA_E_DENSIDADE","prompt":"Escreva lado a lado o total e a área. Divida o primeiro pelo segundo e só então compare os locais."},{"id":"CHECK_SAMPLING","misconception":"AMOSTRA_CONVENIENTE_REPRESENTATIVA","prompt":"Desenhe os tipos de habitat e marque onde houve amostra. Identifique estratos vazios e escolha sorteios adicionais."},{"id":"TRACE_RECAPTURE","misconception":"IGNORAR_VIES_DE_MARCACAO","prompt":"Substitua M, C e R no estimador. Depois aumente ou diminua R para prever a direção do viés."},{"id":"SEPARATE_CAUSE","misconception":"GRAFICO_PROVA_CAUSA","prompt":"Escreva a tendência observada. Liste duas causas alternativas e proponha um controle ou medida adicional."},{"id":"DETECTION_VS_ABUNDANCE","misconception":"CONTAGEM_IGUAL_ABUNDANCIA","prompt":"Pergunte se o ambiente alterou a chance de detectar indivíduos e escolha um método complementar para estimá-la."}],"review_windows_days":[1,3,7],"review_schedule_status":"SUGGESTED_NOT_AUTOMATED","source_dossier":[{"title":"Base Nacional Comum Curricular: Ciências da Natureza e suas Tecnologias","publisher":"Ministério da Educação","url":"https://basenacionalcomum.mec.gov.br/images/BNCC_EI_EF_110518_versaofinal_site.pdf","accessedOn":"2026-10-13","supports":["Contexto geral de investigação e modelagem em Ciências da Natureza no Ensino Médio."],"use":"Referência curricular de contexto; não afirma código ou mapeamento oficial para BIOLOGY_INTERPRET_POPULATION_DATA."},{"title":"Biology 2e, 45.1 Population Demography","publisher":"OpenStax","url":"https://openstax.org/books/biology-2e/pages/45-1-population-demography","accessedOn":"2026-10-13","supports":["Densidade, estrutura etária e estimativa por captura-recaptura."],"use":"Conferência conceitual; explicações, dados e questões deste pacote são autorais."},{"title":"Biology 2e, 45.3 Environmental Limits to Population Growth","publisher":"OpenStax","url":"https://openstax.org/books/biology-2e/pages/45-3-environmental-limits-to-population-growth","accessedOn":"2026-10-13","supports":["Crescimento logístico e capacidade de suporte como modelo."],"use":"Conferência conceitual; explicações, dados e questões deste pacote são autorais."},{"title":"Biology 2e, 45.4 Population Dynamics and Regulation","publisher":"OpenStax","url":"https://openstax.org/books/biology-2e/pages/45-4-population-dynamics-and-regulation","accessedOn":"2026-10-13","supports":["Fatores dependentes/independentes da densidade e limites dos modelos de população."],"use":"Conferência conceitual; explicações, dados e questões deste pacote são autorais."},{"title":"Validation of abundance estimates from mark-recapture and removal techniques for rainbow trout","publisher":"U.S. Geological Survey","url":"https://www.usgs.gov/publications/validation-abundance-estimates-mark-recapture-and-removal-techniques-rainbow-trout","accessedOn":"2026-10-13","supports":["Estimativas por captura-recaptura dependem das premissas do modelo."],"use":"Fonte institucional para reconhecer limitações dos estimadores; o pacote usa dados fictícios autorais."}],"copyright_note":"Questões, cenários, dados e explicações foram escritos para este pacote. As fontes são usadas para conferir conceitos e limites metodológicos, não para reproduzir texto; mapeamento oficial e revisão pedagógica humana permanecem pendentes.","objective":"Interpretar abundância, densidade e tendências populacionais, verificando amostragem, detecção e premissas antes de explicar causas.","common_mistake":"Tratar contagem como densidade, ignorar esforço ou detectabilidade, e atribuir uma tendência a uma única causa sem comparação ou premissas verificadas.","estimated_minutes":24}'::jsonb
  ) on conflict (canonical_skill_id, version) do nothing;
  select id into v_lesson_id from public.learning_skill_lessons
   where canonical_skill_id = v_skill_id and version = 5
     and metadata->>'content_id' = 'v5-biology-population-data' and active = false;
  if v_lesson_id is null then raise exception 'V5_CONTENT_LESSON_CONFLICT'; end if;

  for v_question in
    select * from jsonb_to_recordset('[{"id":"v5-bio-population-probe-01","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"COMPARE","contextFamily":"POPULATION_DENSITY_TWO_RESERVES","statement":"Duas reservas têm área de habitat comparável. Na reserva A foram estimados 240 roedores em 12 km²; na B, 180 em 6 km². Qual afirmação compara corretamente as densidades médias?","options":["A reserva B tem maior densidade: 30 indivíduos/km², contra 20 na A.","A reserva A tem maior densidade porque o total de indivíduos é maior.","As densidades são iguais, pois as áreas têm relação 2 para 1.","Não é possível calcular densidade sem conhecer a idade de cada indivíduo."],"correctAnswer":"A reserva B tem maior densidade: 30 indivíduos/km², contra 20 na A.","explanation":"Densidade relaciona quantidade e área. A tem 240/12 = 20 indivíduos/km²; B tem 180/6 = 30 indivíduos/km². O total sozinho não basta para comparar ocupação por área.","errorFocus":"Comparar abundâncias totais sem usar o denominador da área.","hint":"Divida cada estimativa pela área correspondente antes de comparar.","misconceptions":{"A reserva A tem maior densidade porque o total de indivíduos é maior.":["COMPARAR_ABUND_NCIAS_TOTAIS_SEM_USAR_O_DENOMINADOR_DA_REA"]},"position":1},{"id":"v5-bio-population-probe-02","purpose":"PROBE","difficulty":"EASY","cognitiveProcess":"EVALUATE","contextFamily":"TRAIL_ACCESS_SAMPLING_BIAS","statement":"Para estimar uma população de plantas em uma serra, uma equipe instala quadrantes apenas perto da trilha, onde o terreno é plano. Qual é o principal risco?","options":["O método transforma cada planta em uma unidade de área.","A amostra pode representar mal a serra, pois os locais acessíveis podem diferir do restante do habitat.","A amostra fica automaticamente aleatória por ter vários quadrantes.","O risco é apenas contar a mesma espécie com nomes diferentes."],"correctAnswer":"A amostra pode representar mal a serra, pois os locais acessíveis podem diferir do restante do habitat.","explanation":"Vários quadrantes não eliminam viés se a seleção dos locais favorece áreas acessíveis. Uma amostragem aleatória ou estratificada em habitats distintos melhora a representatividade.","errorFocus":"Confundir muitas observações com seleção representativa.","hint":"Pergunte se a chance de incluir cada parte do habitat foi semelhante.","misconceptions":{"O método transforma cada planta em uma unidade de área.":["CONFUNDIR_MUITAS_OBSERVA_ES_COM_SELE_O_REPRESENTATIVA"]},"position":2},{"id":"v5-bio-population-practice-01","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"MARK_RECAPTURE_RIVER_OTTERS","statement":"Em um estudo de lontras, 120 indivíduos foram marcados e soltos. Depois, uma amostra de 60 foi observada; 10 tinham marca. Pelo estimador simples de captura-recaptura, qual tamanho populacional aproximado é esperado?","options":["72 indivíduos, pois 120 x 10 / 60 = 20.","180 indivíduos, pois 120 + 60 = 180.","720 indivíduos, pois 120 x 60 / 10 = 720.","1 200 indivíduos, pois 120 x 10 = 1 200."],"correctAnswer":"720 indivíduos, pois 120 x 60 / 10 = 720.","explanation":"O estimador simples usa M x C / R: indivíduos marcados inicialmente vezes o tamanho da segunda amostra, dividido pelos marcados recapturados. A estimativa depende de mistura e outras premissas.","errorFocus":"Inverter o número de recapturas ou tratar o resultado como contagem exata.","hint":"Substitua M=120, C=60 e R=10 em N≈M×C/R.","misconceptions":{"72 indivíduos, pois 120 x 10 / 60 = 20.":["INVERTER_O_N_MERO_DE_RECAPTURAS_OU_TRATAR_O_RESULTADO_COMO_CONTAGEM_EXATA"]},"position":1},{"id":"v5-bio-population-practice-02","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"PLATEAU_AFTER_RESOURCE_LIMIT","statement":"Em um vale protegido, estimativas feitas com o mesmo protocolo foram 110, 178, 226, 241 e 238 indivíduos em cinco anos. Qual interpretação é mais compatível com a sequência?","options":["A população deixou de nascer e morrer no quarto ano.","O valor 241 é necessariamente a capacidade de suporte fixa do vale.","A sequência prova que uma única espécie de predador controlou o crescimento.","O crescimento desacelerou e a série se aproximou de um patamar, compatível com limites ambientais no período."],"correctAnswer":"O crescimento desacelerou e a série se aproximou de um patamar, compatível com limites ambientais no período.","explanation":"O aumento inicial seguido de valores próximos sugere desaceleração e possível patamar. A sequência, isoladamente, não determina a causa nem demonstra que a capacidade de suporte seja constante.","errorFocus":"Tratar uma sequência compatível com um modelo como prova de mecanismo ou de valor fixo.","hint":"Descreva a forma da tendência e diferencie modelo compatível de causa comprovada.","misconceptions":{"A população deixou de nascer e morrer no quarto ano.":["TRATAR_UMA_SEQU_NCIA_COMPAT_VEL_COM_UM_MODELO_COMO_PROVA_DE_MECANISMO_OU_DE_VALOR_FIXO"]},"position":2},{"id":"v5-bio-population-practice-03","purpose":"PRACTICE","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"NET_POPULATION_BALANCE_WETLAND","statement":"Em uma área úmida, no intervalo de um ano foram registrados 84 nascimentos, 31 mortes, 12 imigrações e 20 emigrações. Mantidas as definições do levantamento, qual foi a variação líquida estimada?","options":["A população local aumentou em 45 indivíduos.","Aumentou em 115 indivíduos.","Diminuiu em 45 indivíduos.","Aumentou em 23 indivíduos."],"correctAnswer":"A população local aumentou em 45 indivíduos.","explanation":"A variação é nascimentos + imigrações - mortes - emigrações: 84 + 12 - 31 - 20 = 45. É uma estimativa para a área e o intervalo observados.","errorFocus":"Esquecer migração ou subtrair nascimentos e mortes na direção errada.","hint":"Some entradas e subtraia saídas: nascimentos e imigrações entram; mortes e emigrações saem.","misconceptions":{"Aumentou em 115 indivíduos.":["ESQUECER_MIGRA_O_OU_SUBTRAIR_NASCIMENTOS_E_MORTES_NA_DIRE_O_ERRADA"]},"position":3},{"id":"v5-bio-population-transfer-01","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"TAG_LOSS_CAPTURE_RECAPTURE_BIAS","statement":"Uma equipe estima a abundância por captura-recaptura, mas parte das marcas se solta antes da segunda amostragem. Se os animais sem marca forem registrados como não marcados, qual viés tende a ocorrer no estimador M x C / R?","options":["R tende a aumentar e a abundância estimada diminui.","R tende a ficar menor e a abundância estimada, maior, pois o denominador diminui.","A estimativa não muda porque M já foi registrado.","A abundância estimada passa a ser sempre igual ao tamanho da segunda amostra."],"correctAnswer":"R tende a ficar menor e a abundância estimada, maior, pois o denominador diminui.","explanation":"Marcas perdidas fazem alguns animais previamente marcados parecerem novos. Isso reduz as recapturas reconhecidas (R); mantendo M e C, M x C / R aumenta. O método exige marcas persistentes e detectáveis.","errorFocus":"Ignorar como um erro de identificação altera a proporção de recaptura e a estimativa.","hint":"Siga o erro até R e observe o efeito de diminuir o denominador da razão.","misconceptions":{"R tende a aumentar e a abundância estimada diminui.":["IGNORAR_COMO_UM_ERRO_DE_IDENTIFICA_O_ALTERA_A_PROPOR_O_DE_RECAPTURA_E_A_ESTIMATIVA"]},"position":1},{"id":"v5-bio-population-transfer-02","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"RESTORATION_CONTROL_REACHES","statement":"Após restaurar vegetação ciliar em um trecho de rio, uma equipe registra aumento de peixes no trecho restaurado, enquanto um trecho comparável sem intervenção permanece estável. O protocolo e o esforço foram iguais por três anos. Qual conclusão é mais cuidadosa?","options":["A restauração é a única causa possível do aumento.","A comparação prova que todos os peixes migraram do trecho controle.","O padrão é compatível com efeito da restauração, mas fatores não medidos ainda podem explicar parte da diferença.","A estabilidade do controle invalida qualquer comparação entre os trechos."],"correctAnswer":"O padrão é compatível com efeito da restauração, mas fatores não medidos ainda podem explicar parte da diferença.","explanation":"Um local de comparação e protocolos consistentes fortalecem a inferência, mas diferenças prévias, eventos locais e outras variáveis podem permanecer. Mais réplicas e medidas ajudam a testar a hipótese causal.","errorFocus":"Confundir um desenho comparativo informativo com prova de causa exclusiva.","hint":"Use a comparação como evidência, depois liste uma alternativa ainda não controlada.","misconceptions":{"A restauração é a única causa possível do aumento.":["CONFUNDIR_UM_DESENHO_COMPARATIVO_INFORMATIVO_COM_PROVA_DE_CAUSA_EXCLUSIVA"]},"position":2},{"id":"v5-bio-population-transfer-03","purpose":"TRANSFER","difficulty":"HARD","cognitiveProcess":"INTERPRET","contextFamily":"JUVENILE_ADULT_AGE_STRUCTURE","statement":"Duas populações de tartarugas têm 1 000 indivíduos estimados. Na população X, 65% são juvenis; na Y, 20%. O que essa diferença permite dizer sem dados adicionais de sobrevivência e reprodução?","options":["X certamente terá mais adultos reprodutivos no próximo ano.","Y está necessariamente em declínio, pois tem menos juvenis.","As duas populações têm a mesma estrutura etária porque o total é igual.","X tem maior proporção de juvenis, mas isso não determina sozinho qual população crescerá mais."],"correctAnswer":"X tem maior proporção de juvenis, mas isso não determina sozinho qual população crescerá mais.","explanation":"A estrutura etária descreve a composição observada. O recrutamento futuro depende também de sobrevivência, maturação, reprodução e migração; percentuais não garantem uma trajetória.","errorFocus":"Transformar proporção de uma faixa etária em previsão certa de crescimento.","hint":"Separe o que a distribuição etária mostra do que exigiria dados de sobrevivência e fecundidade.","misconceptions":{"X certamente terá mais adultos reprodutivos no próximo ano.":["TRANSFORMAR_PROPOR_O_DE_UMA_FAIXA_ET_RIA_EM_PREVIS_O_CERTA_DE_CRESCIMENTO"]},"position":3},{"id":"v5-bio-population-lock-01","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"COMPARE","contextFamily":"FROST_DENSITY_INDEPENDENT_EVENT","statement":"Uma geada intensa ocorre em duas populações de insetos, uma pouco densa e outra muito densa. Ambas sofrem queda semelhante no mesmo intervalo. Qual fator é mais compatível com o padrão observado?","options":["Um fator independente da densidade, como a geada, pode afetar as populações em ambas as densidades.","Um fator necessariamente dependente da densidade, como competição por alimento.","A capacidade de suporte, que sempre diminui cada população pela mesma quantidade.","A imigração, que só ocorre quando a densidade é baixa."],"correctAnswer":"Um fator independente da densidade, como a geada, pode afetar as populações em ambas as densidades.","explanation":"Um evento climático pode afetar indivíduos sem depender diretamente de quantos há por área. O padrão é compatível com fator independente da densidade, embora outros dados sejam úteis para identificar mecanismos.","errorFocus":"Classificar todo fator ambiental como dependente da densidade.","hint":"Pergunte se a intensidade do efeito descrito exige que a população esteja densa.","misconceptions":{"Um fator necessariamente dependente da densidade, como competição por alimento.":["CLASSIFICAR_TODO_FATOR_AMBIENTAL_COMO_DEPENDENTE_DA_DENSIDADE"]},"position":1},{"id":"v5-bio-population-lock-02","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"ANALYZE","contextFamily":"SEASONAL_CARRYING_CAPACITY","statement":"Uma lagoa tem mais alimento e abrigo no verão; no inverno, a vegetação aquática diminui. As estimativas populacionais variam em torno de um patamar diferente em cada estação. Qual inferência é adequada?","options":["A capacidade de suporte é uma constante universal para cada espécie.","A capacidade de suporte pode variar com as condições sazonais, em vez de ser um número imutável.","Qualquer variação sazonal prova que a estimativa está errada.","A população não pode ultrapassar temporariamente o patamar estimado."],"correctAnswer":"A capacidade de suporte pode variar com as condições sazonais, em vez de ser um número imutável.","explanation":"A capacidade de suporte depende dos recursos e condições do ambiente, que podem mudar no tempo. Um patamar estimado é contextual, não uma constante universal.","errorFocus":"Tratar K como propriedade fixa da espécie, independente do ambiente.","hint":"Relacione o patamar às condições e ao período em que a população foi medida.","misconceptions":{"A capacidade de suporte é uma constante universal para cada espécie.":["TRATAR_K_COMO_PROPRIEDADE_FIXA_DA_ESP_CIE_INDEPENDENTE_DO_AMBIENTE"]},"position":2},{"id":"v5-bio-population-lock-03","purpose":"LOCK_IN","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"RECAPTURE_SAMPLE_MIXING","statement":"Na captura-recaptura, a segunda coleta é feita logo após a soltura, antes que os indivíduos marcados se misturem ao restante da população. Qual problema isso cria?","options":["A estimativa necessariamente fica alta porque M aumenta.","A estimativa permanece imparcial, pois o número marcado é conhecido.","A amostra pode conter proporção excessiva de marcados e levar a uma estimativa populacional baixa.","A população fica maior por causa da marcação."],"correctAnswer":"A amostra pode conter proporção excessiva de marcados e levar a uma estimativa populacional baixa.","explanation":"Sem tempo para mistura, os marcados podem ser recapturados com frequência acima do esperado. Como R fica alto, M x C / R tende a produzir uma estimativa baixa.","errorFocus":"Desconsiderar a premissa de mistura aleatória entre as capturas.","hint":"Considere como R muda quando a segunda coleta ocorre perto demais da soltura.","misconceptions":{"A estimativa necessariamente fica alta porque M aumenta.":["DESCONSIDERAR_A_PREMISSA_DE_MISTURA_ALEAT_RIA_ENTRE_AS_CAPTURAS"]},"position":3},{"id":"v5-bio-population-review-01","purpose":"REVIEW","difficulty":"EASY","cognitiveProcess":"INTERPRET","contextFamily":"QUADRAT_STRATIFIED_MARSH","statement":"Uma várzea tem áreas abertas, margens e ilhas vegetadas. Para estimar a densidade de uma planta em toda a várzea, qual plano reduz melhor o risco de a amostra ignorar um dos ambientes?","options":["Contar somente quadrantes da margem por serem mais acessíveis.","Escolher os pontos com maior quantidade visível de plantas.","Usar um quadrante em cada ambiente e tratá-los como se tivessem a mesma área total.","Sortear quadrantes dentro de cada tipo de ambiente e depois combinar as estimativas considerando a área de cada estrato."],"correctAnswer":"Sortear quadrantes dentro de cada tipo de ambiente e depois combinar as estimativas considerando a área de cada estrato.","explanation":"A amostragem estratificada representa cada ambiente e permite ponderar as estimativas pela área ocupada. Selecionar apenas locais acessíveis ou mais densos introduz viés.","errorFocus":"Confundir uma amostra conveniente com uma amostra que representa toda a área.","hint":"Divida o habitat em estratos e pense em como ponderar áreas de tamanhos diferentes.","misconceptions":{"Contar somente quadrantes da margem por serem mais acessíveis.":["CONFUNDIR_UMA_AMOSTRA_CONVENIENTE_COM_UMA_AMOSTRA_QUE_REPRESENTA_TODA_A_REA"]},"position":1},{"id":"v5-bio-population-review-02","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"CALCULATE","contextFamily":"PER_CAPITA_CHANGE_COLONY","statement":"Uma colônia passa de 500 para 550 indivíduos estimados em um ano, com o mesmo método de contagem. Qual é a variação percentual em relação ao valor inicial?","options":["10%.","50%, pois o aumento foi de 50 indivíduos.","9,1%, pois 50 deve ser dividido pelo valor final.","110%, pois 550 representa 110 indivíduos a mais."],"correctAnswer":"10%.","explanation":"O aumento absoluto é 550 - 500 = 50. Em relação ao valor inicial, 50/500 x 100 = 10%. A porcentagem descreve a estimativa, não identifica sua causa.","errorFocus":"Dividir a diferença pelo valor final ou confundir número absoluto e percentual.","hint":"Use o valor inicial como denominador da variação percentual.","misconceptions":{"50%, pois o aumento foi de 50 indivíduos.":["DIVIDIR_A_DIFEREN_A_PELO_VALOR_FINAL_OU_CONFUNDIR_N_MERO_ABSOLUTO_E_PERCENTUAL"]},"position":2},{"id":"v5-bio-population-review-03","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"COMPARE","contextFamily":"EXPONENTIAL_VS_LOGISTIC_CURVE","statement":"Em um modelo, a população cresce cada vez mais rápido enquanto recursos são abundantes; depois, o crescimento desacelera perto de um patamar. Qual modelo representa melhor essa curva em S?","options":["O modelo exponencial, que mantém aceleração ilimitada para sempre.","O modelo logístico, que incorpora a desaceleração associada a limites ambientais.","Um modelo de tamanho fixo, que não permite variação entre períodos.","Um modelo de migração, mesmo sem dados de entrada ou saída."],"correctAnswer":"O modelo logístico, que incorpora a desaceleração associada a limites ambientais.","explanation":"O crescimento logístico representa aceleração inicial e desaceleração à medida que a população se aproxima de um patamar de suporte. É uma simplificação e o patamar pode mudar.","errorFocus":"Confundir crescimento inicialmente rápido com crescimento exponencial ilimitado em todas as fases.","hint":"Observe se a taxa desacelera quando a população se aproxima do patamar.","misconceptions":{"O modelo exponencial, que mantém aceleração ilimitada para sempre.":["CONFUNDIR_CRESCIMENTO_INICIALMENTE_R_PIDO_COM_CRESCIMENTO_EXPONENCIAL_ILIMITADO_EM_TODAS_AS_FASES"]},"position":3},{"id":"v5-bio-population-review-04","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"CAPTURE_RECAPTURE_CLOSED_POPULATION","statement":"Uma estimativa por captura-recaptura é feita durante um período em que muitos animais entram e saem da área entre as duas coletas. Por que o resultado deve ser interpretado com cautela?","options":["A imigração faz com que nenhuma recaptura possa ocorrer.","O estimador sempre corrige automaticamente qualquer movimento.","A população pode não ser fechada entre amostras, violando uma premissa do estimador simples.","A abundância não pode ser estimada para animais móveis."],"correctAnswer":"A população pode não ser fechada entre amostras, violando uma premissa do estimador simples.","explanation":"O estimador simples pressupõe pouca mudança na população entre capturas, além de mistura e marcas reconhecíveis. Movimento intenso pode alterar as proporções e enviesar a estimativa.","errorFocus":"Aplicar o estimador sem avaliar mudanças entre as ocasiões de captura.","hint":"Compare o intervalo entre amostras com a entrada e saída de indivíduos.","misconceptions":{"A imigração faz com que nenhuma recaptura possa ocorrer.":["APLICAR_O_ESTIMADOR_SEM_AVALIAR_MUDAN_AS_ENTRE_AS_OCASI_ES_DE_CAPTURA"]},"position":4},{"id":"v5-bio-population-review-05","purpose":"REVIEW","difficulty":"MEDIUM","cognitiveProcess":"INTERPRET","contextFamily":"EMIGRATION_VS_MORTALITY_TRACKING","statement":"Uma contagem local cai 30% após uma obra na região. Qual dado ajuda mais a distinguir mortalidade de emigração?","options":["Repetir apenas a contagem no mesmo ponto e horário.","Medir a área total do município sem registrar os animais.","Comparar a contagem com a quantidade de chuva de um único dia.","Acompanhar indivíduos identificáveis em áreas vizinhas e obter dados de sobrevivência ao longo do mesmo período."],"correctAnswer":"Acompanhar indivíduos identificáveis em áreas vizinhas e obter dados de sobrevivência ao longo do mesmo período.","explanation":"Uma queda local pode resultar de morte, saída ou menor detecção. Rastreamento espacial e sobrevivência ajudam a separar essas explicações; a contagem isolada não o faz.","errorFocus":"Interpretar redução local como morte sem medir movimento ou detecção.","hint":"Busque dados que acompanhem os destinos dos indivíduos e sua sobrevivência.","misconceptions":{"Repetir apenas a contagem no mesmo ponto e horário.":["INTERPRETAR_REDU_O_LOCAL_COMO_MORTE_SEM_MEDIR_MOVIMENTO_OU_DETEC_O"]},"position":5},{"id":"v5-bio-population-review-06","purpose":"REVIEW","difficulty":"HARD","cognitiveProcess":"EVALUATE","contextFamily":"DETECTION_CHANGE_DENSE_VEGETATION","statement":"Uma série de aves mostra queda de observações após o crescimento da vegetação, mas o equipamento e o esforço permaneceram iguais. Qual dado adicional é mais útil antes de afirmar que a população diminuiu?","options":["Uma estimativa independente da probabilidade de detecção, ou método complementar que funcione sob a vegetação mais densa.","Uma nova contagem feita apenas no ponto mais aberto.","O número de espécies de plantas, sem medir observabilidade.","A soma das observações antigas e novas como se a detecção fosse constante."],"correctAnswer":"Uma estimativa independente da probabilidade de detecção, ou método complementar que funcione sob a vegetação mais densa.","explanation":"A vegetação pode reduzir a detectabilidade sem alterar a abundância real. Estimar a detecção ou usar método complementar ajuda a distinguir mudança populacional de mudança na observação.","errorFocus":"Supor que esforço igual garante detectabilidade igual em condições diferentes.","hint":"Pergunte se o ambiente mudou a chance de observar cada indivíduo.","misconceptions":{"Uma nova contagem feita apenas no ponto mais aberto.":["SUPOR_QUE_ESFOR_O_IGUAL_GARANTE_DETECTABILIDADE_IGUAL_EM_CONDI_ES_DIFERENTES"]},"position":6}]'::jsonb) as item(
      id text, purpose text, difficulty text, "cognitiveProcess" text,
      "contextFamily" text, statement text, options jsonb, "correctAnswer" text,
      explanation text, hint text, "errorFocus" text, misconceptions jsonb, position integer
    )
  loop
    insert into public.learning_question_sets(scope, canonical_skill_id, purpose, version, active, metadata)
    values ('GLOBAL', v_skill_id, v_question.purpose, 5, false,
      jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', 'v5-biology-population-data',
        'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING', 'publication_status', 'STAGING',
        'bncc_alignment_status', 'NOT_CLAIMED'))
    on conflict (canonical_skill_id, purpose, version) where scope = 'GLOBAL' do nothing;
    select id into v_set_id from public.learning_question_sets
     where scope = 'GLOBAL' and canonical_skill_id = v_skill_id
       and purpose = v_question.purpose and version = 5
       and metadata->>'content_id' = 'v5-biology-population-data' and active = false;
    if v_set_id is null then raise exception 'V5_CONTENT_QUESTION_SET_CONFLICT'; end if;

    select id into v_question_id from public.learning_question_bank
     where source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING' and metadata->>'content_id' = v_question.id;
    if v_question_id is null then
      insert into public.learning_question_bank(
        package_type, source_type, source_name, subject_area, domain, topic,
        statement, options, correct_answer, explanation, difficulty,
        estimated_minutes, provenance, metadata, active
      ) values (
        'TECESCOLA', 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING', 'TecEscola Question First V5 - Staging',
        'BIOLOGY', 'ECOLOGIA', 'dinamica e interpretacao de dados populacionais',
        v_question.statement, v_question.options, to_jsonb(v_question."correctAnswer"),
        v_question.explanation, v_question.difficulty, 2,
        'TECESCOLA_CORE_V5_AUTHORED',
        jsonb_build_object('content_pack', 'TECESCOLA_CORE_V5_QUESTION_FIRST', 'content_id', v_question.id,
          'purpose', v_question.purpose, 'context_family', v_question."contextFamily",
          'cognitive_process', v_question."cognitiveProcess", 'error_focus', v_question."errorFocus",
          'remediation_hint', v_question.hint, 'misconceptions', v_question.misconceptions,
          'content_authoring_status', 'AUTHORED', 'pedagogical_review_status', 'PEDAGOGICAL_REVIEW_PENDING',
          'publication_status', 'STAGING', 'bncc_alignment_status', 'NOT_CLAIMED'), false
      ) returning id into v_question_id;
    end if;
    if v_question_id is null then raise exception 'V5_CONTENT_QUESTION_INSERT_FAILED'; end if;
    update public.learning_question_bank set active = false
     where id = v_question_id and source_type = 'TECESCOLA_CORE_V5_QUESTION_FIRST_STAGING';
    insert into public.learning_question_bank_skill_links(question_bank_id, canonical_skill_id, skill_role)
    values (v_question_id, v_skill_id, 'PRIMARY') on conflict (question_bank_id, canonical_skill_id) do nothing;
    insert into public.learning_question_set_items(question_set_id, question_bank_id, position)
    values (v_set_id, v_question_id, v_question.position)
    on conflict (question_set_id, question_bank_id) do nothing;
  end loop;
end;
$seed_question_first_content_v5$;

